"""Fresh behavioral contrasts motivated by H998; fixed before model outcomes."""
def suite():
 people=['pilot','chef','farmer','singer','teacher','doctor','driver','artist'];locations=['at noon','at dawn','at midnight','at sunset','this morning','last night','on Monday','on Friday'];items=[('apples','pears'),('roses','lilies'),('chairs','tables'),('pens','pencils'),('cats','dogs'),('hats','coats'),('cups','plates'),('books','maps')]
 words=[(' photos','ynthesis','ensitive','Plants convert light into chemical energy through this process','This adjective describes something that reacts to light'),(' phot','ov','ochemistry','This adjective describes converting sunlight directly into electricity','This branch of chemistry studies reactions caused by light'),(' therm','odynamics','opl','This branch of physics studies heat and work','This adjective describes plastic that softens when heated'),(' electro','chemical','static','This adjective concerns chemical reactions involving electrical energy','This adjective concerns electric charges at rest'),(' bi','ochemistry','oph','This science studies the chemical processes of living organisms','This science applies physics to living organisms'),(' neuro','biology','pl','This science studies the biology of the nervous system','This word describes the ability of the brain to reorganize its connections'),(' hydro','electric','carbon','This adjective describes electricity generated using flowing water','This chemical compound contains only hydrogen and carbon'),(' micro','processor','econom','This device is a computer processor on a single chip','This branch of economics studies individual consumers and firms')]
 rows=[]
 for fmt in ['A','B']:
  for i,(person,loc,(a,b)) in enumerate(zip(people,locations,items)):
   def add(f,ps,gg,change,limits=''):
    rows.append(dict(id=f'{f}-{fmt}-{i}',family=f,format=fmt,source=i,split=('discovery' if i<4 else 'lexical') if fmt=='A' else ('structural' if i<4 else 'joint'),whole_task_holdout=False,prompts=ps,answers=['category0','category1'],group_strings=gg,intervention_variable=change,limits=limits))
   clause=f'arrived {loc}' if fmt=='A' else f'finished the work {loc}'
   add('clause_completion',[f'The {person} {clause}',f'The {person} who {clause}'],[['.',',','!','\n'],[' is',' was',' has',' will',' said',' had',' can',' would']],'insert relative-clause marker, fixed subject and last token','Punctuation versus main-clause finite continuation is not exhaustive; comma can be ambiguous. No number/tense cue change.')
   lead='A short list:' if fmt=='A' else 'Items to remember:'
   add('list_marker',[f'{lead}\n1. {a}\n2. {b}\n',f'{lead}\n- {a}\n- {b}\n'],[['3'],['-']],'numbered versus bullet list, same final newline','Related to sequence-pattern continuation; keep diagnostic and do not train on this family while sequence_copy remains a holdout.')
   ps=[f'The {person} used a knife to cut the',f'The {person} used a key to unlock the'] if fmt=='A' else [f'With a knife, the {person} sliced the',f'With a key, the {person} opened the']
   add('noun_expectation',ps,[[' bread',' meat',' cake',' cheese',' vegetables',' fruit',' apple'],[' door',' gate',' car',' lock',' house',' box']],'instrument/action changes expected noun category, fixed final determiner','Two cues covary; broad categories imperfect. Subject nouns vary, but action vocabulary is shared across source splits.')
   stem,s1,s2,d1,d2=words[i];ending='The term is' if fmt=='A' else 'The word is';add('word_fragment',[f'{definition}. {ending}{stem}' for definition in [d1,d2]],[[s1],[s2]],'definition changes continuation of identical current word-fragment token','Scientific-domain cues; next BPE token only, not full-word completion; lexical subfamilies differ across source split.')
 return rows
